package com.cucarell.web.pages.about

import androidx.compose.runtime.Composable
import org.jetbrains.compose.web.dom.H2
import org.jetbrains.compose.web.dom.H3
import org.jetbrains.compose.web.dom.P
import org.jetbrains.compose.web.dom.Text

@Composable
fun Network() {
    H2 { Text("Network migration") }
    P { Text("Sem va demanar migrar la xarxa de Red Hat 5 a CentOS 7.") }
    InitialStat()
    Investigation()
}

@Composable
private fun InitialStat() {
    H3 { Text("Estat inicial") }
    P {
        Text(
            "La configuració del client eren els logs de les comandes." +
                    " Guardava els logs en dos apartats, la configuració local i la de cluster."
        )
    }
    P {
        Text(
            "Comportava certs problemes en les migracions i restaurar la configuració." +

                    " Per començar, executava moltes comandes contradictories (canvi de IP múltiples vegades)," +
                    " cosa que clients que portaven alguns anys tenien decenes de MiB en configuració de xarxa." +

                    " Per continuar, algunes comandes eren molt lentes en ser executades," +
                    " cosa que feia que el client hagués d'esperar molt de temps amb el greu de poder ser" +
                    " alguna comanda que seria sobre escrita." +

                    " Per finalitzar, al ser tant lenta les migracions provocava que els clients evitessin actualitzar" +
                    " el producte. Tenia una experiencia de client molt dolenta."
        )
    }
}

@Composable
private fun Investigation() {
    H3 { Text("Investigació") }
    P {
        Text(
            "Abans, cada comanda modificava directament els fitxers y restaurava la xarxa." +
                    " Algunes vegades provocava estats inconsistents, poden fer fallar la propia xarxa degut a que" +
                    " no sabia acabat de configurar tots els valors."
        )
    }
    /* TODO
    ** - fitxers -> NetworkManager
    *  - Només modificar fitxers la config
     */
}
