private fun MutableList<LongRange>.myAdd(range: LongRange) {
    val firstOrNull: LongRange? = firstOrNull { lr -> lr myIntersect range }

    if (firstOrNull == null) {
        add(range)
        return
    }

    remove(firstOrNull)
    add(
        minOf(firstOrNull.first, range.first)..maxOf(firstOrNull.last, range.last)
    )
}

