    org.jetbrains.compose.web.dom.Pre { org.jetbrains.compose.web.dom.Code { org.jetbrains.compose.web.dom.Text("""sealed class Values {
    data class Register(val char: Char) : Values()
    data class Value(val int: Int) : Values()
    companion object {
        fun of(input: String): Values = when {
            input in "a".."d" -> Register(input.toCharArray().first())
            else -> Value(input.toInt())
        }
    }
}

sealed class Instructions {
    data class Copies(val from: Values, val to: Values.Register) : Instructions()
    data class Increases(val register: Values.Register) : Instructions()
    data class Decreases(val register: Values.Register) : Instructions()
    data class Jumps(val conditional: Values, val jump: Values.Value) : Instructions()
}
""") } }
    org.jetbrains.compose.web.dom.P {
        org.jetbrains.compose.web.dom.Text("Llavors només hem d'executar les instruccions una per una per poder saber quin valor tindrà el registre ")
