class SequenceObject(init: Coordinates, val seed: UInt) {
    var count: Int = 0
    var nextSteps: Set<Coordinates> = setOf(init)
    val history: MutableSet<Coordinates> = mutableSetOf(init)

    fun execute(): Sequence<SequenceObject> = sequence {
        while (nextSteps.isNotEmpty()) {
            nextSteps = nextSteps
                .asSequence()
                .flatMap { step: Coordinates -> step.children() }
                .filter { step: Coordinates -> step.getType(seed) == Type.OpenSpace }
                .filter { step: Coordinates -> step !in history }
                .toSet()
            history += nextSteps
            count++
            yield(this@SequenceObject)
        }
    }
}
