private fun lineToRotation(input: String): Rotation {
    val key: Char = input.first()
    val value: Int = input.drop(1).toIntOrNull() ?: error("this is invalid input <${'$'}input>")

    return when (key) {
        'L' -> Rotation.Left(value)
        'R' -> Rotation.Right(value)
        else -> error("invalid input <${'$'}input>")
    }
